def adjust_for_splits(prices, metadata):
    """Adjust prices for corporate actions (splits)."""
    adjusted = {}
    for date in sorted(prices.keys()):
        adjusted[date] = {}
        for ticker in prices[date]:
            if ticker in metadata:
                split_info = metadata[ticker].get('split_history', '')
                if split_info:
                    # Parse split info like "2:1 split effective 2024-05-24"
                    # Find the date part (last word) and the ratio part (first word with colon)
                    words = split_info.split()
                    split_date = None
                    ratio = 1.0
                    for word in words:
                        if ':' in word:
                            ratio_parts = word.split(':')
                            ratio = float(ratio_parts[0]) / float(ratio_parts[1])
                        elif word.endswith('effective'):
                            # The date is the next word
                            if len(words) > words.index(word) + 1:
                                split_date = parse_date(words[words.index(word) + 1])
                    # Adjust all prices after the split date
                    if split_date:
                        for d in sorted(prices.keys()):
                            if d >= split_date:
                                adjusted[d][ticker] = prices[d][ticker] / ratio
                            else:
                                adjusted[d][ticker] = prices[d][ticker]
                    else:
                        for d in sorted(prices.keys()):
                            adjusted[d][ticker] = prices[d][ticker]
                    continue
            adjusted[date][ticker] = prices[date][ticker]
    return adjusted
